using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property name
            // EF Core 9 defaults to "$type" instead of "Discriminator".
            // Our 500K existing documents and direct SQL queries use "Discriminator".
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format
            // EF Core 9 no longer prepends the discriminator to the id.
            //   EF8 format:  "Product|123"
            //   EF9 default: "123"
            // Opt back in so existing documents remain readable.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .HasValueGenerator<Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.Internal.IdValueGenerator>();
            // NOTE: There is no single-line opt-in for the old id format. The
            // simplest backward-compatible approach is to store the id property
            // with the legacy prefix using a value converter:
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // BREAKING CHANGE 3 — Sync I/O removed
        // EF Core 9 Cosmos provider no longer supports synchronous APIs
        // (ToList, First, SaveChanges, etc.). All call sites must be async.
        // See CosmosQuery.cs for the updated usage.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

