class CosmosQuery
{
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still references "Discriminator" (kept via HasDiscriminator config)
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // BREAKING CHANGE 3: Sync APIs (ToList, First, SaveChanges, etc.) are
        // removed in the EF Core 9 Cosmos provider. Use async equivalents.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

