using Microsoft.EntityFrameworkCore;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and direct SQL
            // queries reference c.Discriminator.  Keep the old name:
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — JSON "id" format changed
            // EF8: id = "Product|123"   (discriminator + "|" + key)
            // EF9: id = "123"           (key only)
            // Existing documents use the old format, so we must preserve it.
            // Map a shadow property to the JSON "id" and generate values in
            // the legacy "EntityType|Key" format.
#pragma warning disable EF1001 // Internal EF Core API usage — required for backward compat
            entity.Property<string>("__id")
                  .HasJsonPropertyName("id")
                  .HasValueGeneratorFactory<
                      Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.Internal.IdValueGeneratorFactory>();
#pragma warning restore EF1001

            // BREAKING CHANGE 3 — HasIndex() not supported
            // EF Core 9 Cosmos provider throws for HasIndex.
            // The EF8 call was silently ignored; it is removed here.
            // Cosmos indexing is configured via the Azure portal / indexing policy.
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // BREAKING CHANGE 4 — Sync I/O removed
        // EF Core 9 Cosmos provider no longer supports synchronous APIs
        // (ToList, First, SaveChanges, etc.).  All call sites must use
        // their async equivalents.  See CosmosQuery.cs.
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

